const participants = $input.all();
let maxNumber = 0;
for (const item of participants) {
  const pid = String(item.json.ParticipantID || item.json['Participant ID'] || item.json.participantId || '');
  const match = pid.match(/\d+/);
  if (match) {
    const num = parseInt(match[0], 10);
    if (!isNaN(num) && num > maxNumber) {
      maxNumber = num;
    }
  }
}
const nextNumber = maxNumber > 0 ? maxNumber + 1 : (participants.length + 1);
const participantId = `EVT-${String(nextNumber).padStart(6, '0')}`;
const teamId = `TEAM-${String(1000 + nextNumber)}`;

const body = $('W1-Reg: Webhook').first().json.body || {};

return [{
  json: {
    participantId,
    teamId: body.teamId || teamId,
    eventId: body.eventId || 'EVT-H-001',
    timestamp: body.timestamp || new Date().toISOString(),
    fullName: body.fullName || body.name || 'Participant',
    email: body.email || '',
    phone: body.phone || '',
    college: body.college || '',
    event: body.event || 'AI Innovation Hackathon',
    consent: body.consent || true
  }
}];

const body = $input.first().json.body;

return [
  {
    json: {
      participantId: body.participantId,
      name: body.name,
      event: body.event,
      checkInTime: new Date().toISOString()
    }
  }
];

